const cmds=["cat project/PROBLEM.md","tail -100 project/iteration-log.md","cat project/search/search_state.md","python - <<'PY'
import json
r=json.load(open('project/experiments/registry.json'))
print('keys',list(r)); print('search',r.get('search')); print('head',r.get('head')); print('candidates',len(r.get('candidates',{})))
for k,v in list(r.get('candidates',{}).items())[-12:]: print(k,v)
PY","cat hardware.json && cat project/recipe.json && rg -n '^def |^class ' project/compiler.py project/search/*.py"];
const rs=await Promise.allSettled(cmds.map(cmd=>tools.exec_command({cmd,max_output_tokens:5000}))); rs.forEach((r,i)=>text(`--- ${i+1} ---
${r.status==="fulfilled"?r.value.output:r.reason}`));

