"""Single writer, bounded evaluator scheduling and exact artifact reuse."""
from concurrent.futures import ThreadPoolExecutor
from contextlib import contextmanager
from dataclasses import dataclass, field
from pathlib import Path
import copy
import fcntl
import json
import threading
import time

from . import state
from .candidate import EXPERIMENTS, Candidate


@dataclass
class Budget:
    maximum: int = 12
    wall_seconds: float = 7200
    used: int = 0
    audit_path: Path | None = None
    started: float = field(default_factory=time.monotonic)
    lock: threading.Lock = field(default_factory=threading.Lock, repr=False)

    def claim(self, mode, candidate=None):
        with self.lock:
            if self.used >= self.maximum or time.monotonic() - self.started >= self.wall_seconds:
                raise RuntimeError('evaluation_budget_exhausted')
            self.used += 1
            if self.audit_path:
                self.audit_path.parent.mkdir(parents=True, exist_ok=True)
                with self.audit_path.open("a") as stream:
                    stream.write(json.dumps({"launch": self.used, "mode": mode,
                                             "candidate": candidate, "time": time.time()}) + "\n")

    def available(self):
        return self.used < self.maximum and time.monotonic() - self.started < self.wall_seconds

    def summary(self):
        return {'used': self.used, 'maximum': self.maximum,
                'wall_seconds': round(time.monotonic() - self.started, 3)}


@contextmanager
def writer_lock():
    """Prevent two independent controller processes from writing the registry."""
    EXPERIMENTS.mkdir(parents=True, exist_ok=True)
    with (EXPERIMENTS / '.controller.lock').open('a') as stream:
        try:
            fcntl.flock(stream, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except BlockingIOError:
            raise RuntimeError('another search controller is active') from None
        try:
            yield
        finally:
            fcntl.flock(stream, fcntl.LOCK_UN)


def recover(reg):
    """Called under writer lock; no previous coordinator can still own work."""
    from .records import record_result
    for cid, meta in list(reg['candidates'].items()):
        cand = Candidate.load(cid)
        if meta.get('status') != 'evaluating' and cand.status != 'evaluating':
            continue
        path = cand.dir / 'metrics.json'
        metrics = json.loads(path.read_text()) if path.exists() else {
            'candidate': cid, 'reports': {}, 'verdict': 'not_verified',
            'failure_class': 'interrupted', 'failure_note': 'Recovered incomplete evaluation',
            'evaluation_attempts': 0,
        }
        path.write_text(json.dumps(metrics, indent=2) + '\n')
        record_result(reg, cand, metrics)
    state.save(reg)


def evaluate_many(reg, candidates, seeds, budget, *, jobs=2, validation='grade',
                  timeout_seconds=600, memory_mib=3072, force=False):
    """Only evaluation subprocesses run in parallel; state/cache writes stay here."""
    from . import cache, evaluator
    from .records import record_result
    jobs = max(1, min(int(jobs), 2))
    results = []
    candidates = list(candidates)

    def finish(cand, metrics, key=None):
        metrics['candidate'] = cand.id
        (cand.dir / 'metrics.json').write_text(json.dumps(metrics, indent=2) + '\n')
        record_result(reg, cand, metrics)
        if key and not metrics.get('cache_hit'):
            cache.store(key, cand, metrics)
        state.save(reg)
        results.append(metrics)
        score = metrics.get('reports', {}).get('grade', {}).get('score')
        print(f'[{cand.id}] {metrics.get("verdict")} score={score} budget={budget.used}/{budget.maximum}', flush=True)

    with ThreadPoolExecutor(max_workers=jobs) as pool:
        for start in range(0, len(candidates), jobs):
            wave = []
            for cand in candidates[start:start + jobs]:
                if (cand.dir / 'metrics.json').exists() or list(cand.reports.glob('*.json')):
                    raise FileExistsError(f'{cand.id} has results; create a new candidate/attempt')
                cand.status = 'evaluating'; cand.save()
                reg['candidates'][cand.id]['status'] = 'evaluating'; state.save(reg)
                try:
                    prepared = evaluator.prepare(cand, timeout_seconds=timeout_seconds, memory_mib=memory_mib)
                    if prepared.get('failure_class') or prepared.get('verdict') in ('not_verified', 'pruned'):
                        finish(cand, prepared); continue
                    key = cache.execution_key(cand, seeds, validation)
                    hit = None if force else cache.lookup(key)
                    if hit:
                        hit = copy.deepcopy(hit)
                        source = hit.get('candidate')
                        hit.update(cache_hit=True, cache_source=source, evaluation_attempts=0)
                        finish(cand, hit); continue
                    duplicate = next((item for item in wave if item[2] == key), None)
                    if duplicate:
                        wave.append((cand, duplicate[1], key, True)); continue
                    if not budget.available():
                        finish(cand, {'reports': {}, 'verdict': 'not_verified',
                                      'failure_class': 'budget_exhausted', 'evaluation_attempts': 0}); continue
                    fut = pool.submit(evaluator.evaluate, cand, seeds, validation=validation,
                                      timeout_seconds=timeout_seconds, memory_mib=memory_mib,
                                      prepared=True, before_launch=lambda mode, cid=cand.id: budget.claim(mode, cid))
                    wave.append((cand, fut, key, False))
                except Exception as exc:
                    finish(cand, {'reports': {}, 'verdict': 'not_verified',
                                  'failure_class': 'prepare_error', 'failure_note': str(exc),
                                  'evaluation_attempts': 0})
            # Integrate in proposal order, independent of worker completion order.
            for cand, fut, key, duplicate in wave:
                try:
                    metrics = copy.deepcopy(fut.result())
                except Exception as exc:
                    metrics = {'reports': {}, 'verdict': 'not_verified',
                               'failure_class': 'evaluator_error', 'failure_note': str(exc)}
                if duplicate:
                    source = metrics.get('candidate')
                    metrics.update(cache_hit=True, cache_source=source, evaluation_attempts=0)
                    if metrics.get('verdict') != 'evaluated':
                        metrics.update(verdict='not_verified', failure_class='duplicate_unverified')
                finish(cand, metrics, None if duplicate else key)
    return results
"""Candidate record: one point in the (hardware, program) design space.

A candidate owns an immutable inputs/ snapshot (compiler.py + hardware.json),
the programs generated from them, evaluator reports, a parsed metrics.json,
and a verdict. Everything under project/experiments/<id>/ is written once and
then treated as read-only evidence.
"""

import hashlib
import json
import time
from dataclasses import asdict, dataclass, field
from pathlib import Path

REPO = Path(__file__).resolve().parents[2]
EXPERIMENTS = REPO / "project" / "experiments"

# Files that define a candidate's design point. Everything else (generated asm,
# reports, metrics) is derived and reproducible.
INPUT_FILES = ("compiler.py", "hardware.json")
# Optional inputs: staged when present, removed from the worktree when absent.
OPTIONAL_INPUT_FILES = ("recipe.json",)
WORKTREE_PATHS = {
    "compiler.py": REPO / "project" / "compiler.py",
    "hardware.json": REPO / "hardware.json",
    "recipe.json": REPO / "project" / "recipe.json",
}
PROGRAM_FILES = ("M1_P1.asm", "M2_D1.asm")
STATUSES = ("created", "evaluating", "incorrect", "evaluated", "kept",
            "reverted", "pruned", "dominated")


def sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


@dataclass
class Candidate:
    id: str
    parent: str | None
    hypothesis: str
    summary: str
    created_at: str = field(default_factory=lambda: time.strftime("%Y-%m-%d %H:%M:%S"))
    status: str = "created"
    verdict_note: str | None = None
    # CandidateNode fields for autonomous search.
    ops: list | None = None
    family: str | None = None
    bias: str | None = None
    kind: str | None = None          # exploit | expand | novelty | manual
    round: int | None = None
    struct_sig: str | None = None
    fingerprint: str | None = None
    failure_class: str | None = None
    provenance_note: str | None = None

    @property
    def dir(self) -> Path:
        return EXPERIMENTS / self.id

    @property
    def inputs(self) -> Path:
        return self.dir / "inputs"

    @property
    def reports(self) -> Path:
        return self.dir / "reports"

    @property
    def programs(self) -> Path:
        return self.dir / "programs"

    def path(self, name: str) -> Path:
        return self.dir / name

    def save(self) -> None:
        self.dir.mkdir(parents=True, exist_ok=True)
        for sub in (self.inputs, self.reports, self.programs):
            sub.mkdir(exist_ok=True)
        (self.dir / "candidate.json").write_text(
            json.dumps(asdict(self), indent=2, sort_keys=True) + "\n"
        )

    @classmethod
    def load(cls, cid: str) -> "Candidate":
        data = json.loads((EXPERIMENTS / cid / "candidate.json").read_text())
        return cls(**data)

    def input_hashes(self) -> dict:
        names = [n for n in INPUT_FILES + OPTIONAL_INPUT_FILES
                 if (self.inputs / n).exists()]
        return {name: sha256(self.inputs / name) for name in names}

    def stage_to_worktree(self) -> None:
        """Copy candidate inputs into the live repo files."""
        for name in INPUT_FILES:
            src = self.inputs / name
            if not src.exists():
                raise FileNotFoundError(f"Candidate {self.id} missing input {name}")
            WORKTREE_PATHS[name].write_bytes(src.read_bytes())
        for name in OPTIONAL_INPUT_FILES:
            src = self.inputs / name
            dst = WORKTREE_PATHS[name]
            if src.exists():
                dst.write_bytes(src.read_bytes())
            elif dst.exists():
                dst.unlink()

    def snapshot_from_worktree(self) -> None:
        """Capture the live repo files as this candidate's inputs."""
        for name in INPUT_FILES:
            src = WORKTREE_PATHS[name]
            if not src.exists():
                raise FileNotFoundError(f"Worktree missing {src}")
            (self.inputs / name).write_bytes(src.read_bytes())
        for name in OPTIONAL_INPUT_FILES:
            src = WORKTREE_PATHS[name]
            if src.exists():
                (self.inputs / name).write_bytes(src.read_bytes())
"""Execution artifact cache and content-addressed execution keys.

Prevents redundant expensive simulator runs by hashing:
  1. Canonical hardware configuration
  2. Emitted assembly programs (M1_P1.asm, M2_D1.asm)
  3. Frozen evaluator tree and baseline manifest
  4. Pinned Python / NumPy runtime environment
  5. Validation mode and seed set

Only complete, eligible, functionally correct evaluations may be stored or reused.
Cache hits link the authoritative source candidate rather than fabricating fake raw reports.
"""

from __future__ import annotations

import copy
import hashlib
import json
import os
import tempfile
import time
from pathlib import Path
from typing import Any

from .candidate import EXPERIMENTS, REPO

DEFAULT_CACHE_FILE = EXPERIMENTS / "execution_cache.json"
BASELINE_MANIFEST_PATH = REPO / "baseline_manifest.json"
CODESIGN_DIR = REPO / "codesign"

PINNED_RUNTIME = {
    "python": "3.12.13",
    "numpy": "2.5.3",
}

_CACHED_EVALUATOR_TREE_HASH: str | None = None
_CACHED_BASELINE_MANIFEST_HASH: str | None = None


def sha256_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def sha256_file(path: Path) -> str:
    return sha256_bytes(path.read_bytes())


def canonical_json_bytes(obj: Any) -> bytes:
    return json.dumps(obj, sort_keys=True, separators=(",", ":")).encode("utf-8")


def get_evaluator_tree_hash(codesign_dir: Path | None = None) -> str:
    """Compute deterministic SHA-256 over all files in the codesign tree."""
    global _CACHED_EVALUATOR_TREE_HASH
    target_dir = codesign_dir or CODESIGN_DIR
    if codesign_dir is None and _CACHED_EVALUATOR_TREE_HASH is not None:
        return _CACHED_EVALUATOR_TREE_HASH

    if not target_dir.exists():
        digest = sha256_bytes(b"empty_codesign_tree")
    else:
        entries = []
        for file_path in sorted(target_dir.rglob("*")):
            if file_path.is_file():
                rel = file_path.relative_to(target_dir).as_posix()
                entries.append(f"{rel}:{sha256_file(file_path)}")
        digest = sha256_bytes("\n".join(entries).encode("utf-8"))

    if codesign_dir is None:
        _CACHED_EVALUATOR_TREE_HASH = digest
    return digest


def get_baseline_manifest_hash(manifest_path: Path | None = None) -> str:
    """Compute deterministic SHA-256 of the baseline manifest."""
    global _CACHED_BASELINE_MANIFEST_HASH
    target = manifest_path or BASELINE_MANIFEST_PATH
    if manifest_path is None and _CACHED_BASELINE_MANIFEST_HASH is not None:
        return _CACHED_BASELINE_MANIFEST_HASH

    if not target.exists():
        digest = sha256_bytes(b"missing_baseline_manifest")
    else:
        digest = sha256_file(target)

    if manifest_path is None:
        _CACHED_BASELINE_MANIFEST_HASH = digest
    return digest


def input_fingerprint(cand: Any) -> str:
    """Produce deterministic hash of candidate inputs: compiler, recipe, hardware, deps.

    Captures:
      - compiler.py (bytes)
      - hardware.json (canonical JSON)
      - recipe.json (canonical JSON if present)
      - any other staged files in cand.inputs
      - declared candidate dependencies if any
    """
    inputs_dir = getattr(cand, "inputs", None)
    hashes: dict[str, str] = {}

    if isinstance(inputs_dir, Path) and inputs_dir.exists():
        for item in sorted(inputs_dir.iterdir()):
            if item.is_file():
                if item.suffix == ".json":
                    try:
                        parsed = json.loads(item.read_text(encoding="utf-8"))
                        hashes[item.name] = sha256_bytes(canonical_json_bytes(parsed))
                    except Exception:
                        hashes[item.name] = sha256_file(item)
                else:
                    hashes[item.name] = sha256_file(item)

    # Include declared dependencies if candidate defines them
    deps = getattr(cand, "declared_dependencies", None) or getattr(cand, "dependencies", None)
    if deps is not None:
        hashes["_declared_dependencies"] = sha256_bytes(canonical_json_bytes(deps))

    items = [f"{name}:{h}" for name, h in sorted(hashes.items())]
    return sha256_bytes(";".join(items).encode("utf-8"))


def execution_key(
    cand: Any,
    seeds: list[int] | None = None,
    validation: str = "grade",
    codesign_dir: Path | None = None,
    baseline_path: Path | None = None,
) -> str:
    """Compute content-addressed execution key for simulator output equivalence.

    Includes:
      - canonical hardware JSON
      - generated assembly hashes (M1_P1.asm, M2_D1.asm)
      - evaluator tree and baseline manifest hashes
      - pinned Python / NumPy runtime environment versions
      - validation mode ("grade", "check", "estimate")
      - seeds list
    """
    # 1. Canonical hardware hash
    hw_hash = "missing"
    inputs_dir = getattr(cand, "inputs", None)
    hw_path = (inputs_dir / "hardware.json") if isinstance(inputs_dir, Path) else None
    if hw_path and hw_path.exists():
        try:
            hw_obj = json.loads(hw_path.read_text(encoding="utf-8"))
            hw_hash = sha256_bytes(canonical_json_bytes(hw_obj))
        except Exception:
            hw_hash = sha256_file(hw_path)
    elif (REPO / "hardware.json").exists():
        try:
            hw_obj = json.loads((REPO / "hardware.json").read_text(encoding="utf-8"))
            hw_hash = sha256_bytes(canonical_json_bytes(hw_obj))
        except Exception:
            hw_hash = sha256_file(REPO / "hardware.json")

    # 2. Generated assembly hashes
    asm_hashes: dict[str, str] = {}
    programs_dir = getattr(cand, "programs", None)
    for name in ("M1_P1.asm", "M2_D1.asm"):
        p = (programs_dir / name) if isinstance(programs_dir, Path) else None
        if p and p.exists():
            asm_hashes[name] = sha256_file(p)
        elif (REPO / "programs" / name).exists():
            asm_hashes[name] = sha256_file(REPO / "programs" / name)
        else:
            asm_hashes[name] = "missing"

    # 3. Evaluator tree and baseline manifest
    eval_tree_hash = get_evaluator_tree_hash(codesign_dir)
    manifest_hash = get_baseline_manifest_hash(baseline_path)

    # 4. Canonical seeds
    canon_seeds = sorted(int(s) for s in (seeds or []))

    # Combine into canonical key dictionary
    key_dict = {
        "asm_hashes": asm_hashes,
        "baseline_manifest_hash": manifest_hash,
        "evaluator_tree_hash": eval_tree_hash,
        "hardware_hash": hw_hash,
        "mode": validation,
        "runtime": PINNED_RUNTIME,
        "seeds": canon_seeds,
    }
    return sha256_bytes(canonical_json_bytes(key_dict))


def _load_cache(cache_path: Path | None = None) -> dict:
    target = cache_path or DEFAULT_CACHE_FILE
    if target.exists():
        try:
            return json.loads(target.read_text(encoding="utf-8"))
        except Exception:
            return {}
    return {}


def _save_cache(data: dict, cache_path: Path | None = None) -> None:
    target = cache_path or DEFAULT_CACHE_FILE
    target.parent.mkdir(parents=True, exist_ok=True)
    serialized = json.dumps(data, indent=2, sort_keys=True) + "\n"
    tmp_fd, tmp_path = tempfile.mkstemp(
        dir=target.parent,
        prefix=f".{target.name}.tmp-",
    )
    try:
        with os.fdopen(tmp_fd, "w", encoding="utf-8") as f:
            f.write(serialized)
            f.flush()
            os.fsync(f.fileno())
        os.replace(tmp_path, target)
    except Exception:
        if os.path.exists(tmp_path):
            os.unlink(tmp_path)
        raise


def is_cacheable(metrics: dict) -> bool:
    """Return True only if evaluation is complete, eligible, and functionally correct."""
    if not isinstance(metrics, dict):
        return False
    reports = metrics.get("reports", {})
    grade = reports.get("grade", {}) if isinstance(reports, dict) else {}
    if not isinstance(grade, dict):
        return False

    # Check score presence
    score = grade.get("score") if grade.get("score") is not None else metrics.get("score")
    if score is None:
        return False

    # Must be eligible
    eligible = grade.get("eligible") if "eligible" in grade else metrics.get("eligible")
    if eligible is not True:
        return False

    # Must pass functional on all cases
    cases = grade.get("cases", {})
    if not cases or not isinstance(cases, dict):
        return False
    for case, c_data in cases.items():
        if not isinstance(c_data, dict) or c_data.get("functional_passed") is not True:
            return False

    verdict = metrics.get("verdict")
    if verdict not in (None, "evaluated"):
        return False

    failure_class = metrics.get("failure_class")
    if failure_class not in (None, "none"):
        return False

    return True


def lookup(key: str, cache_path: Path | None = None) -> dict | None:
    """Look up execution key; returns metrics copy or None.

    Only complete evaluated eligible true functional true reports are reused.
    Enriches metrics with source candidate linkage rather than fabricating raw reports.
    """
    cache = _load_cache(cache_path)
    entry = cache.get(key)
    if not entry or not isinstance(entry, dict):
        return None

    entry_metrics = entry.get("metrics")
    if not entry_metrics or not is_cacheable(entry_metrics):
        return None

    reused = copy.deepcopy(entry_metrics)
    reused["cached"] = True
    reused["cache_hit"] = True
    reused["cache_key"] = key
    reused["source_candidate"] = entry.get("candidate_id")
    reused["cached_from"] = entry.get("candidate_id")
    return reused


def store(key: str, cand: Any, metrics: dict, cache_path: Path | None = None) -> bool:
    """Store evaluated result into cache under key.

    Only complete evaluated eligible true functional true reports are stored.
    Returns True if stored, False if rejected by qualification gates.
    """
    if not is_cacheable(metrics):
        return False

    cache = _load_cache(cache_path)
    cid = getattr(cand, "id", None) or str(cand)
    score = (
        metrics.get("reports", {}).get("grade", {}).get("score")
        if isinstance(metrics.get("reports"), dict)
        else metrics.get("score")
    )

    cache[key] = {
        "candidate_id": cid,
        "eligible": True,
        "functional_passed": True,
        "metrics": copy.deepcopy(metrics),
        "score": score,
        "status": "evaluated",
        "stored_at": time.strftime("%Y-%m-%d %H:%M:%S"),
    }
    _save_cache(cache, cache_path)
    return True


def link_source_candidate(cand: Any, source_candidate_id: str) -> None:
    """Link candidate to source candidate artifacts without fabricating raw reports."""
    reports_dir = getattr(cand, "reports", None)
    if isinstance(reports_dir, Path) and reports_dir.exists():
        ref_file = reports_dir / "cached_from.json"
        ref_data = {
            "cached_from": source_candidate_id,
            "linked_at": time.strftime("%Y-%m-%d %H:%M:%S"),
            "note": "Reused evaluation artifacts; authoritative raw reports live on source candidate.",
        }
        ref_file.write_text(json.dumps(ref_data, indent=2, sort_keys=True) + "\n")


def index_v2_evaluations(
    experiments_dir: Path | None = None,
    cache_path: Path | None = None,
    candidate_ids: list[str] | None = None,
) -> dict[str, list[str]]:
    """Index eligible v2 evaluations into the cache.

    By default indexes v2 candidates (cand-071, cand-072, cand-073) where full
    verification artifacts and eligibility gates are confirmed.
    """
    from .candidate import Candidate

    exp_dir = experiments_dir or EXPERIMENTS
    target_ids = candidate_ids or ["cand-071", "cand-072", "cand-073"]
    indexed: list[str] = []
    skipped: list[str] = []

    for cid in target_ids:
        cand_dir = exp_dir / cid
        if not cand_dir.exists():
            skipped.append(f"{cid}: directory not found")
            continue
        try:
            cand = Candidate.load(cid) if exp_dir == EXPERIMENTS else None
            if cand is None:
                # Custom experiments dir
                cand_data = json.loads((cand_dir / "candidate.json").read_text(encoding="utf-8"))
                cand = Candidate(**cand_data)

            metrics_file = cand.dir / "metrics.json"
            if not metrics_file.exists():
                skipped.append(f"{cid}: missing metrics.json")
                continue
            metrics = json.loads(metrics_file.read_text(encoding="utf-8"))
            if not is_cacheable(metrics):
                skipped.append(f"{cid}: not cacheable (failed eligibility or functional check)")
                continue

            # Compute execution key for standard grade validation on seed 7
            key = execution_key(cand, seeds=[7], validation="grade")
            if store(key, cand, metrics, cache_path=cache_path):
                indexed.append(cid)
            else:
                skipped.append(f"{cid}: store rejected")
        except Exception as e:
            skipped.append(f"{cid}: error {e}")

    return {"indexed": indexed, "skipped": skipped}


