    cand: Any,
    metrics: dict,
    meta: dict,
    log_path: Path | None = None,
    promoted: bool = False,
) -> None:
    """Append one iteration-log entry per finalized candidate.

    Includes cache hits and failures with evidence and elapsed.
    Must never throw on missing errors or missing fields.
    """
