def register_operator(name: str, fn) -> None:
    """Agents may register new structural operators here."""
    OPERATORS[name] = fn


def check_phase(ops: list[dict], phase: int) -> None:
    unlocked = PHASE_UNLOCKED_OPS[phase]
    for op in ops:
        if op["op"] not in OPERATORS:
            raise DslError(f"unknown operator {op['op']!r}")
        if op["op"] not in unlocked:
            raise OperatorLocked(f"operator {op['op']!r} locked at phase {phase}")


def canonicalize_hardware(hw: dict) -> dict:
    """Enforce canonical dependencies on hardware dictionary."""
    h = copy.deepcopy(hw)
    tc_cnt = h.get("tc_count", 0)
    if tc_cnt == 0:
        h.pop("tc_array", None)
        h.pop("tc_k_parallel", None)
    else:
        if h.get("tc_array") is None:
            h["tc_array"] = "4x8"
        if h.get("tc_k_parallel") is None:
            h["tc_k_parallel"] = 1

    sh_kib = h.get("shared_kib", 0)
    if sh_kib == 0:
        h.pop("shared_banks", None)
        h.pop("shared_ports", None)
    else:
        if h.get("shared_banks") is None:
            h["shared_banks"] = 4
        if h.get("shared_ports") is None:
            h["shared_ports"] = "1R1W"

    if "vector_lanes" in h and "sfu_lanes" in h:
        vl = h["vector_lanes"]
        if h["sfu_lanes"] > vl:
            h["sfu_lanes"] = vl
        elif h["sfu_lanes"] < 1:
            h["sfu_lanes"] = 1
    return h


def apply_ops(base_recipe: dict, base_hw: dict, ops: list[dict],
              phase: int = 1) -> tuple[dict, dict]:
    check_phase(ops, phase)
    recipe = copy.deepcopy(base_recipe)
    hw = copy.deepcopy(base_hw)
    for op in ops:
        OPERATORS[op["op"]](recipe, hw, op)
    # Canonicalize: fields the compiler ignores must not create distinct
    # fingerprints (e.g. prefetch is only implemented in the nkm path).
    if recipe.get("gemm", {}).get("order") != "nkm":
        if "gemm" in recipe and "prefetch" in recipe["gemm"]:
            recipe["gemm"]["prefetch"] = 0
    hw = canonicalize_hardware(hw)
    return recipe, hw


def lane_words(hw: dict | None = None) -> int:
    """RF words per lane = 64KiB private slot / vector_lanes."""
    vl = (hw or {}).get("vector_lanes", 16)
    return (64 * 1024 // 4) // vl


def validate_recipe(recipe: dict, hw: dict | None = None) -> list[str]:
    """Static resource/divisibility pruning. Returns reasons; empty = legal."""
    errs = []
    if "gemm" not in recipe:
        return ["missing gemm in recipe"]
    g = recipe["gemm"]
    order = g.get("order")
    m_t = g.get("m_tile", 0)
    n_t = g.get("n_tile", 0)
    k_c = g.get("k_chunk", 0)
    lw = lane_words(hw)
    if order == "nkm":
        # All m accumulators for one n-tile are simultaneously live in lane 2.
        if MAX_M * n_t > lw:
            errs.append(f"nkm: m_extent*n_tile={MAX_M*n_t}>{lw}")
    elif order == "mnk":
        if m_t * n_t > lw:
            errs.append(f"mnk: m_tile*n_tile={m_t*n_t}>{lw}")
    else:
        errs.append(f"unknown order {order!r}")
    if k_c * n_t > lw:
        errs.append(f"B tile k_chunk*n_tile={k_c*n_t}>{lw}")
    if m_t * k_c > lw:
        errs.append(f"A tile m_tile*k_chunk={m_t*k_c}>{lw}")
    # scores live in lane 4; worst case row length = 136 (D1 past+8).
    if recipe.get("attention", {}).get("scores") == "rf" and 136 > lw:
        errs.append(f"scores_rf: 136>{lw} lane words")
    # m_tile<=2 explodes expanded instruction count (cand-033 pathology).
    if MAX_M // max(m_t, 1) > 32:
        errs.append(f"m_tile={m_t}: >32 m-iterations, instruction explosion")
    if recipe.get("attention", {}).get("scores") not in SCORES_SPACES:
        errs.append("bad scores space")
    for stage, override in recipe.get("gemm_stages", {}).items():
        if stage not in ("p1_prompt", "p1_step", "d1"):
            errs.append(f"bad GEMM stage {stage!r}")
            continue
        if not isinstance(override, dict):
            errs.append(f"stage {stage} override must be dict")
            continue
        if set(override) - {"m_tile", "n_tile", "k_chunk"}:
            errs.append(f"unsupported GEMM stage fields: {set(override) - {'m_tile', 'n_tile', 'k_chunk'}}")
            continue
        for k, v in override.items():
            choices = {"m_tile": M_TILE_CHOICES, "n_tile": N_TILE_CHOICES, "k_chunk": K_CHUNK_CHOICES}[k]
            if type(v) is not int or v not in choices:
                errs.append(f"{stage}: {k}={v!r} not in {choices}")
        effective = {**g, **override}
        st_m, st_n, st_k = (effective["m_tile"], effective["n_tile"], effective["k_chunk"])
        max_rows = 64 if stage == "p1_prompt" else 1
        if effective.get("order") == "nkm" and max_rows * st_n > lw:
            errs.append(f"{stage}: accumulators exceed RF lane")
        elif effective.get("order") == "mnk" and st_m * st_n > lw:
            errs.append(f"{stage}: accumulators exceed RF lane")
        if st_m * st_k > lw:
            errs.append(f"{stage}: operand tile A exceeds RF lane")
        if st_k * st_n > lw:
            errs.append(f"{stage}: operand tile B exceeds RF lane")
        if max_rows // max(st_m, 1) > 32:
            errs.append(f"{stage}: too many m iterations")
    return errs


def validate_hardware(hw: dict) -> list[str]:
    """Menu + area pruning using the evaluator's own cost model."""
    errs = []
    try:
        from codesign.challenge.hardware import Hardware
        h = Hardware.from_dict(hw)
        h.validate()
    except Exception as e:
        return [f"hardware invalid: {e}"]
    area = h.area_mm2()
    if area > AREA_LIMIT_MM2:
        errs.append(f"area {area:.2f}mm2 > {AREA_LIMIT_MM2}")
    return errs


def fingerprint(recipe: dict, hw: dict, compiler: str | None = None,
                compiler_id: str | None = None) -> str:
    cid = compiler if compiler is not None else compiler_id
    data = {"r": recipe, "h": hw}
    if cid is not None:
        data["c"] = str(cid)
    blob = json.dumps(data, sort_keys=True)
    import hashlib
    return hashlib.sha256(blob.encode()).hexdigest()[:16]


def structure_signature(recipe: dict, hw: dict | None = None) -> str:
    parts = []
    g = recipe.get("gemm", {})
    order = g.get("order", "mnk")
    parts.append(order)
    parts.append("pf" if g.get("prefetch") else "nopf")
    scores = recipe.get("attention", {}).get("scores", "hbm")
    parts.append(f"s:{scores}")
    bias_gelu = recipe.get("fusion", {}).get("bias_gelu", 0)
    parts.append("fuse" if bias_gelu else "nofuse")
    for st in sorted(recipe.get("gemm_stages", {})):
        parts.append(f"stage:{st}")

    if hw:
        tc_cnt = hw.get("tc_count", BASELINE_HW["tc_count"])
        if tc_cnt != BASELINE_HW["tc_count"]:
            parts.append(f"hw:tc_count={tc_cnt}")
        if tc_cnt > 0:
            if hw.get("tc_array") and hw.get("tc_array") != BASELINE_HW["tc_array"]:
                parts.append(f"hw:tc_array={hw['tc_array']}")
            if hw.get("tc_k_parallel") and hw.get("tc_k_parallel") != BASELINE_HW["tc_k_parallel"]:
                parts.append(f"hw:tc_k_parallel={hw['tc_k_parallel']}")
        sh_kib = hw.get("shared_kib", BASELINE_HW["shared_kib"])
        if sh_kib != BASELINE_HW["shared_kib"]:
            parts.append(f"hw:shared_kib={sh_kib}")
        if sh_kib > 0:
            if hw.get("shared_banks") and hw.get("shared_banks") != BASELINE_HW["shared_banks"]:
                parts.append(f"hw:shared_banks={hw['shared_banks']}")
            if hw.get("shared_ports") and hw.get("shared_ports") != BASELINE_HW["shared_ports"]:
                parts.append(f"hw:shared_ports={hw['shared_ports']}")
        for k in ("sm_count", "vector_lanes", "sfu_lanes", "reduction_units",
                  "rf_ports", "dma_depth", "dma_engines", "sm_noc_bytes_per_cycle",
                  "multicast", "noc_bytes_per_cycle", "hbm_channels", "cache_mib"):
            if k in hw and hw[k] != BASELINE_HW.get(k):
                parts.append(f"hw:{k}={hw[k]}")

    return "+".join(sorted(parts)) or "base"


def recipe_diff(a: dict, b: dict) -> dict:
    """Flat diff of two recipes: {dotted.path: [old, new]}."""
    out = {}

    def walk(x, y, p):
        if isinstance(x, dict) and isinstance(y, dict):
            for k in sorted(set(x) | set(y)):
                walk(x.get(k), y.get(k), f"{p}{k}.")
        elif x != y:
            out[p[:-1]] = [x, y]

    walk(a, b, "")
    return out
    return ops


def propose_round(reg: dict, round_no: int, count: int,
                  explore_ratio: float, phase: int,
                  rng: random.Random,
                  diagnostics: dict | None = None) -> list[dict]:
    """Emit proposals strictly meeting quotas without truncation stealing novelty."""
    from .archives import best_id
    best = best_id(reg)
    if not best:
        best = next(iter(reg.get("candidates", {})), "cand-000")
    tried = _tried_fingerprints(reg)

    if diagnostics is not None:
        diagnostics.setdefault("rejections", [])
        diagnostics.setdefault("rejection_reasons", {})
        diagnostics.setdefault("attempts", 0)

    def record_rejection(reason: str, kind: str, ops: list[dict], parent: str):
        if diagnostics is not None:
            diagnostics["rejections"].append(reason)
            # Use base reason key for summary counts
            base_reason = reason.split(":")[0]
            diagnostics["rejection_reasons"][base_reason] = (
                diagnostics["rejection_reasons"].get(base_reason, 0) + 1
            )

    attempts = 0
    exploit_proposals = []
    expand_proposals = []
    novelty_proposals = []

    def emit(parent: str, ops: list[dict], family: str, bias: str, kind: str,
             hypothesis: str, target_list: list[dict], target_quota: int) -> bool:
        nonlocal attempts
        if attempts >= 128:
            return False
        attempts += 1
        if diagnostics is not None:
            diagnostics["attempts"] = attempts
        if len(target_list) >= target_quota:
            record_rejection("quota_full", kind, ops, parent)
            return False
        try:
            recipe, hw = _load_parent_inputs(parent)
        except Exception as e:
            record_rejection(f"parent_load_error: {e}", kind, ops, parent)
            return False
        try:
            recipe, hw = dsl.apply_ops(recipe, hw, ops, phase=phase)
        except dsl.DslError as e:
            record_rejection(f"dsl_error: {e}", kind, ops, parent)
            return False
        r_errs = dsl.validate_recipe(recipe, hw)
        if r_errs:
            record_rejection(f"recipe_invalid: {'; '.join(r_errs)}", kind, ops, parent)
            return False
        hw_errs = dsl.validate_hardware(hw)
        if hw_errs:
            record_rejection(f"hardware_invalid: {'; '.join(hw_errs)}", kind, ops, parent)
            return False
        fp = dsl.fingerprint(recipe, hw, compiler=_compiler_identity(parent))
        if fp in tried:
            record_rejection(f"duplicate_fingerprint: {fp}", kind, ops, parent)
            return False
        tried.add(fp)
        sig = dsl.structure_signature(recipe, hw)
        target_list.append({
            "parent": parent, "ops": ops, "family": family, "bias": bias,
            "kind": kind, "hypothesis": hypothesis,
            "recipe": recipe, "hardware": hw, "fingerprint": fp,
            "struct_sig": sig,
        })
        return True

    # Quota allocation
    if count == 6:
        target_exploit = 2
        target_expand = 2
        target_novelty = 2
    else:
        target_novelty = max(1, int(round(count * explore_ratio)))
        rem = count - target_novelty
        target_expand = max(1, rem // 2) if rem > 1 else max(0, rem)
        target_exploit = max(0, count - target_novelty - target_expand)

    # --- 1. EXPLOIT: single-param neighbourhood of incumbent ---
    base_recipe, base_hw = _load_parent_inputs(best)
    g = base_recipe["gemm"]
    base_tiles = (g["m_tile"], g["n_tile"], g["k_chunk"])
    order = g["order"]
    extras = []
    if g.get("prefetch"):
        extras.append({"op": "gemm_prefetch", "enabled": 1})
    if base_recipe.get("attention", {}).get("scores") == "rf":
        extras.append({"op": "scores_residency", "space": "rf"})
    if base_recipe.get("fusion", {}).get("bias_gelu"):
        extras.append({"op": "fuse_bias_gelu", "enabled": 1})

    gemm_nbrs = []
    for axis, idx in (("m_tile", 0), ("n_tile", 1), ("k_chunk", 2)):
        choices = {"m_tile": dsl.M_TILE_CHOICES, "n_tile": dsl.N_TILE_CHOICES,
                   "k_chunk": dsl.K_CHUNK_CHOICES}[axis]
        if base_tiles[idx] not in choices:
            continue
        cur = choices.index(base_tiles[idx])
        for step in (-1, 1, -2, 2):
            j = cur + step
            if 0 <= j < len(choices):
                t = list(base_tiles)
                t[idx] = choices[j]
                gemm_nbrs.append((_mk_ops(order, tuple(t), extras),
                                 _meta(reg, best).get("family", "memory"),
                                 f"tiles {base_tiles}->{tuple(t)}"))

    stage_nbrs = [
        ([op], "compute", f"stage tile {op['stage']}")
        for op in stage_tile_neighborhood(base_recipe)
    ]

    hw_nbrs = []
    if phase >= 2:
        for field, menu in dsl.HW_MENU.items():
            cur_v = base_hw.get(field)
            if cur_v not in menu:
                continue
            ci = menu.index(cur_v)
            for step in (-1, 1):
                j = ci + step
                if 0 <= j < len(menu):
                    hw_nbrs.append(([{"op": "hw_set", "path": field, "value": menu[j]}],
                                    "hardware", f"hw {field} {cur_v}->{menu[j]}"))

    rng.shuffle(gemm_nbrs)
    rng.shuffle(stage_nbrs)
    rng.shuffle(hw_nbrs)

    all_exploit = []
    max_exploit_len = max(len(gemm_nbrs), len(stage_nbrs), len(hw_nbrs), 1)
    for i in range(max_exploit_len):
        if i < len(gemm_nbrs):
            all_exploit.append(gemm_nbrs[i])
        if i < len(stage_nbrs):
            all_exploit.append(stage_nbrs[i])
        if i < len(hw_nbrs):
            all_exploit.append(hw_nbrs[i])

    exploit_attempts = 0
    for ops, fam, desc in all_exploit:
        if len(exploit_proposals) >= target_exploit or exploit_attempts >= 128:
            break
        exploit_attempts += 1
        emit(best, ops, fam, _meta(reg, best).get("bias", "balanced"),
             "exploit", f"exploit {best}: {desc}",
             exploit_proposals, target_exploit)

    # --- 2. EXPAND: mutate archive parents ---
    hw_toggles = [
        ({"op": "hw_set", "path": "rf_ports", "value": "8R4W"}, "hardware",
         "widen RF ports to relieve MMA read-port bound"),
        ({"op": "hw_set", "path": "dma_depth", "value": 2}, "memory",
         "dma_depth=2 to make prefetch overlap"),
        ({"op": "hw_set", "path": "dma_engines", "value": 2}, "memory",
         "second DMA engine"),
        ({"op": "hw_set", "path": "reduction_units", "value": 1}, "compute",
         "reduction unit for LN/softmax reduces"),
        ({"op": "hw_set", "path": "cache_mib", "value": 2}, "memory",
         "2MiB cache behind HBM"),
        ({"op": "hw_set", "path": "hbm_channels", "value": 8}, "memory",
         "double HBM channels"),
        ({"op": "hw_set", "path": "tc_array", "value": "8x8"}, "compute",
         "wider TC array 8x8"),
        ({"op": "hw_set", "path": "tc_array", "value": "8x16"}, "compute",
         "wider TC array 8x16"),
        ({"op": "hw_set", "path": "tc_k_parallel", "value": 2}, "compute",
         "k-parallel TC (2)"),
        ({"op": "hw_set", "path": "tc_k_parallel", "value": 4}, "compute",
         "k-parallel TC (4)"),
        ({"op": "hw_set", "path": "sm_noc_bytes_per_cycle", "value": 128},
         "memory", "wider SM NoC link"),
        ({"op": "hw_set", "path": "sfu_lanes", "value": 16}, "compute",
         "wider SFU lanes"),
        ({"op": "hw_set", "path": "shared_banks", "value": 8}, "memory",
         "more shared memory banks"),
        ({"op": "hw_set", "path": "shared_ports", "value": "2R1W"}, "memory",
         "faster shared memory ports"),
        ({"op": "hw_set", "path": "multicast", "value": True}, "memory",
         "enable multicast"),
    ]

    arch = reg.get("archives", {})
    parents = []
    pool = (arch.get("pareto", []) + arch.get("elite", [])
            + list(arch.get("diversity", {}).values())
            + [c for c, m in reg.get("candidates", {}).items()
               if m.get("score") is not None
               and m.get("status") not in ("dominated", "pruned", "incorrect")])
    for cid in pool:
        if cid != best and cid in reg.get("candidates", {}) and cid not in parents:
            parents.append(cid)
    if not parents:
        parents = [best]

    expand_attempts = 0
    for parent in parents:
        if len(expand_proposals) >= target_expand or expand_attempts >= 128:
            break
        pr, phw = _load_parent_inputs(parent)
        pg = pr.get("gemm", {})
        toggles = [
            ([{"op": "scores_residency", "space": "rf"}], "attention",
             f"expand {parent}: keep attention scores in RF"),
            ([{"op": "fuse_bias_gelu", "enabled": 1}], "fusion",
             f"expand {parent}: fuse bias+gelu epilogue"),
            ([{"op": "gemm_prefetch", "enabled": 1}], "memory",
             f"expand {parent}: double-buffer B tiles"),
        ]
        # Include stage tile toggles in expand
        for st_op in stage_tile_neighborhood(pr)[:4]:
            toggles.append(([st_op], "compute", f"expand {parent}: stage tile {st_op['stage']}"))

        if phase >= 2:
            toggles += [
                ([dict(op)], fam, f"expand {parent}: {hyp} [{op['path']}={op['value']}]")
                for op, fam, hyp in hw_toggles
                if phw.get(op["path"]) != op["value"]
            ]
        rng.shuffle(toggles)
        for op_list, fam, hyp in toggles:
            if len(expand_proposals) >= target_expand or expand_attempts >= 128:
                break
            # Skip if parent already configured with this setting
            already = False
            for op in op_list:
                if op["op"] == "scores_residency" and pr.get("attention", {}).get("scores") == op["space"]:
                    already = True
                elif op["op"] == "fuse_bias_gelu" and pr.get("fusion", {}).get("bias_gelu") == op["enabled"]:
                    already = True
                elif op["op"] == "gemm_prefetch" and pg.get("prefetch") == op["enabled"]:
                    already = True
                elif op["op"] == "hw_set" and phw.get(op["path"]) == op["value"]:
                    already = True
            if already:
                record_rejection("already_configured", "expand", op_list, parent)
                continue

            expand_attempts += 1
            emit(parent, op_list, fam, _meta(reg, parent).get("bias", "balanced"),
                 "expand", hyp, expand_proposals, target_expand)

    # --- 3. NOVELTY: prefer untried structural signatures, then random legal ---
    sigs_tried = {m.get("struct_sig") for c, m in reg.get("candidates", {}).items()
                  if not c.startswith("drun-")}
    for p in exploit_proposals + expand_proposals:
        sigs_tried.add(p["struct_sig"])

    candidates_structs = [
        (s, fam, ops) for s, (fam, ops) in STRUCTURES.items()
        if struct_sig(ops) not in sigs_tried
    ]
    rng.shuffle(candidates_structs)
    novelty_attempts = 0
    for sname, fam, ops in candidates_structs:
        if len(novelty_proposals) >= target_novelty or novelty_attempts >= 128:
            break
        novelty_attempts += 1
        emit(best, ops, fam, "balanced", "novelty",
             f"novelty: untried structure {sname} on {best}",
             novelty_proposals, target_novelty)

    while len(novelty_proposals) < target_novelty and novelty_attempts < 128:
        novelty_attempts += 1
        order = rng.choice(dsl.GEMM_ORDERS)
        tiles = rng.choice(legal_tiles(order))
        extra_ops = [
            {"op": "gemm_prefetch", "enabled": rng.randint(0, 1)},
            {"op": "scores_residency", "space": rng.choice(dsl.SCORES_SPACES)},
            {"op": "fuse_bias_gelu", "enabled": rng.randint(0, 1)},
        ]
        if rng.random() < 0.5:
            stg = rng.choice(["p1_prompt", "d1", "p1_step"])
            if stg == "p1_prompt":
                extra_ops.append({"op": "stage_gemm_tiles", "stage": stg,
                                  "m_tile": rng.choice([8, 16, 32])})
            else:
                extra_ops.append({"op": "stage_gemm_tiles", "stage": stg,
                                  "n_tile": rng.choice([16, 32, 64]),
                                  "k_chunk": rng.choice([16, 32, 64])})
        ops = _mk_ops(order, tiles, extra_ops)
        if phase >= 2 and rng.random() < 0.5:
            field = rng.choice(list(dsl.HW_MENU))
            val = rng.choice(list(dsl.HW_MENU[field]))
            ops.append({"op": "hw_set", "path": field, "value": val})
        emit(best, ops, "memory", "balanced", "novelty",
             f"novelty: random {order} tiles={tiles}",
             novelty_proposals, target_novelty)

    if diagnostics is not None:
        diagnostics["quota_requested"] = {"exploit": target_exploit, "expand": target_expand, "novelty": target_novelty}
        diagnostics["quota_filled"] = {"exploit": len(exploit_proposals), "expand": len(expand_proposals), "novelty": len(novelty_proposals)}
    # Proposals assembled strictly respecting quotas; NO truncation stealing novelty
    proposals = exploit_proposals + expand_proposals + novelty_proposals
    return proposals

