def check_phase(ops: list[dict], phase: int) -> None:
    unlocked = PHASE_UNLOCKED_OPS[phase]
    for op in ops:
        if op["op"] not in OPERATORS:
            raise DslError(f"unknown operator {op['op']!r}")
        if op["op"] not in unlocked:
            raise OperatorLocked(f"operator {op['op']!r} locked at phase {phase}")


def canonicalize_hardware(hw: dict) -> dict:
    """Enforce canonical dependencies on hardware dictionary."""
    h = copy.deepcopy(hw)
    tc_cnt = h.get("tc_count", 0)
    if tc_cnt == 0:
        h.pop("tc_array", None)
        h.pop("tc_k_parallel", None)
    else:
        if h.get("tc_array") is None:
            h["tc_array"] = "4x8"
        if h.get("tc_k_parallel") is None:
            h["tc_k_parallel"] = 1

    sh_kib = h.get("shared_kib", 0)
    if sh_kib == 0:
        h.pop("shared_banks", None)
        h.pop("shared_ports", None)
    else:
        if h.get("shared_banks") is None:
            h["shared_banks"] = 4
        if h.get("shared_ports") is None:
            h["shared_ports"] = "1R1W"

    if "vector_lanes" in h and "sfu_lanes" in h:
        vl = h["vector_lanes"]
        if h["sfu_lanes"] > vl:
            h["sfu_lanes"] = vl
        elif h["sfu_lanes"] < 1:
            h["sfu_lanes"] = 1
    return h


def apply_ops(base_recipe: dict, base_hw: dict, ops: list[dict],
              phase: int = 1) -> tuple[dict, dict]:
    check_phase(ops, phase)
    recipe = copy.deepcopy(base_recipe)
    hw = copy.deepcopy(base_hw)
    for op in ops:
        OPERATORS[op["op"]](recipe, hw, op)
    # Canonicalize: fields the compiler ignores must not create distinct
    # fingerprints (e.g. prefetch is only implemented in the nkm path).
    if recipe.get("gemm", {}).get("order") != "nkm":
        if "gemm" in recipe and "prefetch" in recipe["gemm"]:
            recipe["gemm"]["prefetch"] = 0
    hw = canonicalize_hardware(hw)
    return recipe, hw


def lane_words(hw: dict | None = None) -> int:
    """RF words per lane = 64KiB private slot / vector_lanes."""
    vl = (hw or {}).get("vector_lanes", 16)
    return (64 * 1024 // 4) // vl


def validate_recipe(recipe: dict, hw: dict | None = None) -> list[str]:
    """Static resource/divisibility pruning. Returns reasons; empty = legal."""
    errs = []
    if "gemm" not in recipe:
        return ["missing gemm in recipe"]
    g = recipe["gemm"]
    order = g.get("order")
    m_t = g.get("m_tile", 0)
    n_t = g.get("n_tile", 0)
    k_c = g.get("k_chunk", 0)
    lw = lane_words(hw)
    if order == "nkm":
        # All m accumulators for one n-tile are simultaneously live in lane 2.
        if MAX_M * n_t > lw:
            errs.append(f"nkm: m_extent*n_tile={MAX_M*n_t}>{lw}")
    elif order == "mnk":
        if m_t * n_t > lw:
            errs.append(f"mnk: m_tile*n_tile={m_t*n_t}>{lw}")
    else:
        errs.append(f"unknown order {order!r}")
    if k_c * n_t > lw:
        errs.append(f"B tile k_chunk*n_tile={k_c*n_t}>{lw}")
    if m_t * k_c > lw:
        errs.append(f"A tile m_tile*k_chunk={m_t*k_c}>{lw}")
    # scores live in lane 4; worst case row length = 136 (D1 past+8).
    if recipe.get("attention", {}).get("scores") == "rf" and 136 > lw:
        errs.append(f"scores_rf: 136>{lw} lane words")
    # m_tile<=2 explodes expanded instruction count (cand-033 pathology).
    if MAX_M // max(m_t, 1) > 32:
        errs.append(f"m_tile={m_t}: >32 m-iterations, instruction explosion")
    if recipe.get("attention", {}).get("scores") not in SCORES_SPACES:
        errs.append("bad scores space")
    for stage, override in recipe.get("gemm_stages", {}).items():
        if stage not in ("p1_prompt", "p1_step", "d1"):
            errs.append(f"bad GEMM stage {stage!r}")
            continue
        if not isinstance(override, dict):
            errs.append(f"stage {stage} override must be dict")
            continue
        if set(override) - {"m_tile", "n_tile", "k_chunk"}:
            errs.append(f"unsupported GEMM stage fields: {set(override) - {'m_tile', 'n_tile', 'k_chunk'}}")
            continue
        for k, v in override.items():
            choices = {"m_tile": M_TILE_CHOICES, "n_tile": N_TILE_CHOICES, "k_chunk": K_CHUNK_CHOICES}[k]
            if type(v) is not int or v not in choices:
                errs.append(f"{stage}: {k}={v!r} not in {choices}")
        effective = {**g, **override}
        st_m, st_n, st_k = (effective["m_tile"], effective["n_tile"], effective["k_chunk"])
        max_rows = 64 if stage == "p1_prompt" else 1
        if effective.get("order") == "nkm" and max_rows * st_n > lw:
            errs.append(f"{stage}: accumulators exceed RF lane")
        elif effective.get("order") == "mnk" and st_m * st_n > lw:
            errs.append(f"{stage}: accumulators exceed RF lane")
        if st_m * st_k > lw:
            errs.append(f"{stage}: operand tile A exceeds RF lane")
        if st_k * st_n > lw:
            errs.append(f"{stage}: operand tile B exceeds RF lane")
        if max_rows // max(st_m, 1) > 32:
            errs.append(f"{stage}: too many m iterations")
    return errs
"""Candidate record: one point in the (hardware, program) design space.

A candidate owns an immutable inputs/ snapshot (compiler.py + hardware.json),
the programs generated from them, evaluator reports, a parsed metrics.json,
and a verdict. Everything under project/experiments/<id>/ is written once and
then treated as read-only evidence.
"""

import hashlib
import json
import time
from dataclasses import asdict, dataclass, field
from pathlib import Path

REPO = Path(__file__).resolve().parents[2]
EXPERIMENTS = REPO / "project" / "experiments"

# Files that define a candidate's design point. Everything else (generated asm,
# reports, metrics) is derived and reproducible.
INPUT_FILES = ("compiler.py", "hardware.json")
# Optional inputs: staged when present, removed from the worktree when absent.
OPTIONAL_INPUT_FILES = ("recipe.json",)
WORKTREE_PATHS = {
    "compiler.py": REPO / "project" / "compiler.py",
    "hardware.json": REPO / "hardware.json",
    "recipe.json": REPO / "project" / "recipe.json",
}
PROGRAM_FILES = ("M1_P1.asm", "M2_D1.asm")
STATUSES = ("created", "evaluating", "incorrect", "evaluated", "kept",
            "reverted", "pruned", "dominated", "not_verified", "ineligible")


def sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


@dataclass
class Candidate:
    id: str
    parent: str | None
    hypothesis: str
    summary: str
    created_at: str = field(default_factory=lambda: time.strftime("%Y-%m-%d %H:%M:%S"))
    status: str = "created"
    verdict_note: str | None = None
    # CandidateNode fields for autonomous search.
    ops: list | None = None
    family: str | None = None
    bias: str | None = None
    kind: str | None = None          # exploit | expand | novelty | manual
    round: int | None = None
    struct_sig: str | None = None
    fingerprint: str | None = None
    failure_class: str | None = None
    provenance_note: str | None = None

    @property
    def dir(self) -> Path:
        return EXPERIMENTS / self.id

    @property
    def inputs(self) -> Path:
        return self.dir / "inputs"

    @property
    def reports(self) -> Path:
        return self.dir / "reports"

    @property
    def programs(self) -> Path:
        return self.dir / "programs"

    def path(self, name: str) -> Path:
        return self.dir / name

    def save(self) -> None:
        self.dir.mkdir(parents=True, exist_ok=True)
        for sub in (self.inputs, self.reports, self.programs):
            sub.mkdir(exist_ok=True)
        (self.dir / "candidate.json").write_text(
            json.dumps(asdict(self), indent=2, sort_keys=True) + "\n"
        )

    @classmethod
    def load(cls, cid: str) -> "Candidate":
        data = json.loads((EXPERIMENTS / cid / "candidate.json").read_text())
        return cls(**data)

    def input_hashes(self) -> dict:
        names = [n for n in INPUT_FILES + OPTIONAL_INPUT_FILES
                 if (self.inputs / n).exists()]
        return {name: sha256(self.inputs / name) for name in names}

    def stage_to_worktree(self) -> None:
        """Copy candidate inputs into the live repo files."""
        for name in INPUT_FILES:
            src = self.inputs / name
            if not src.exists():
                raise FileNotFoundError(f"Candidate {self.id} missing input {name}")
            WORKTREE_PATHS[name].write_bytes(src.read_bytes())
        for name in OPTIONAL_INPUT_FILES:
            src = self.inputs / name
            dst = WORKTREE_PATHS[name]
            if src.exists():
                dst.write_bytes(src.read_bytes())
            elif dst.exists():
                dst.unlink()

    def snapshot_from_worktree(self) -> None:
        """Capture the live repo files as this candidate's inputs."""
        for name in INPUT_FILES:
            src = WORKTREE_PATHS[name]
            if not src.exists():
                raise FileNotFoundError(f"Worktree missing {src}")
            (self.inputs / name).write_bytes(src.read_bytes())
        for name in OPTIONAL_INPUT_FILES:
            src = WORKTREE_PATHS[name]
            if src.exists():
                (self.inputs / name).write_bytes(src.read_bytes())
"""Isolated evaluator: generate -> expanded static screen -> grade.

The only ground truth is challenge.py. This module runs it as a subprocess and
parses the written report files; it never interprets or scores anything itself.
"""

import json
import os
import subprocess
import sys
import time
from pathlib import Path

REPO = Path(__file__).resolve().parents[2]
BASELINE_MANIFEST = REPO / "baseline_manifest.json"


def python_exe() -> str:
    exe = os.environ.get("CHALLENGE_PYTHON")
    if exe:
        return exe
    venv = REPO / ".venv" / "bin" / "python"
    return str(venv) if venv.exists() else sys.executable


def summarize(report: dict) -> dict:
    """Reduce a check/estimate/grade report to the metrics we compare on."""
    out = {"mode": report.get("mode"), "cases": {}}
    if "experimental_score" in report:
        out["score"] = report["experimental_score"]
        out["eligible"] = report.get("eligible")
        out["area_mm2"] = report.get("gate_diagnostics", {}).get("area_mm2")
    for case, block in report.get("cases", {}).items():
        entry = {"functional_passed": block.get("functional_passed")}
        errors = [
            c.get("max_absolute_error")
            for c in block.get("functional", [])
            for c in c.get("checks", {}).values()
        ]
        if errors:
            entry["max_abs_error"] = max(e for e in errors if e is not None)
        timing = block.get("timing")
        if timing:
            entry["cycles"] = timing["cycles"]
            entry["instruction_count"] = timing["instruction_count"]
            entry["hbm_read_bytes"] = timing["hbm_read_bytes"]
            entry["hbm_write_bytes"] = timing["hbm_write_bytes"]
            entry["peak_window_power_w"] = timing["peak_window_power_w"]
            stats = timing.get("resource_stats") or {}
            busy = {}
            for sm, s in (stats.get("sms") or {}).items():
                for res, cyc in (s.get("busy_cycles") or {}).items():
                    busy[f"sm{sm}.{res}"] = cyc
                busy[f"sm{sm}.issue_wait"] = s.get("issue_wait_cycles")
            for res, cyc in (stats.get("shared", {}).get("busy_cycles") or {}).items():
                busy[f"shared.{res}"] = cyc
            entry["busy_cycles"] = busy
        out["cases"][case] = entry
    return out


