        hw[path] = value
        if hw.get("sfu_lanes", 1) > value:
            hw["sfu_lanes"] = value
        return
    elif path == "tc_count":
        hw[path] = value
        if value == 0:
            hw.pop("tc_array", None)
            hw.pop("tc_k_parallel", None)
        else:
            if hw.get("tc_array") is None:
                hw["tc_array"] = "4x8"
            if hw.get("tc_k_parallel") is None:
                hw["tc_k_parallel"] = 1
        return
